(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const mod = await import('node-tsv-json');
  const tsv = mod.default || mod;
  const { inputPath, outputPath } = globalThis;
  await new Promise((resolve, reject) => {
    tsv({ input: inputPath, output: outputPath }, (err, result) => {
      if (err) return reject(err);
      globalThis.result = result;
      resolve();
    });
  });
})();

(async () => {
  const outputPath = globalThis.outputPath;
  if (!outputPath) throw new Error('OUTPUT_PATH not set');
  console.log(JSON.stringify({ output_path: outputPath }));
})();
